  // highest-priority log status for (me, absence date, give-up period)
  function logStatusFor(log, meId, dateAbsentISO, per){
    var prio={'อนุมัติแล้ว':4,'รออนุมัติ':3,'เสนอ':2,'ยกเลิก':1};
    var bestP=0, st='', nm='', impact='—';
    for(var i=0;i<(log||[]).length;i++){
      var e=log[i];
      if(e.me_id===meId && e.date_absent===dateAbsentISO && String(e.per_give)===String(per)){
        var p=prio[e.status]||0;
        if(p>bestP){ bestP=p; st=e.status; nm=e.y_name||''; impact=e.impact_tag||'—'; }
      }
    }
    return {status:st, name:nm, impact:impact};
  }

  // one dashboard row (POC formula port). cls drives the colour band.
  function dashStatus(eng, me, day, per, dateAbsentISO, log){
    var row = eng.row(me, day, per);
    var isLunch = (eng.displayLunch(me, day) === per);
    var o = {period:per, subjGroup:'', room:'', status:'', cls:'na', impact:'—', swappable:false};
    if(!row){                                              // J = 0
      if(isLunch){ o.subjGroup='พักกลางวัน'; o.status='— (พักกลางวัน)'; }
      else       { o.subjGroup='— คาบว่าง';  o.status='ไม่ต้องสลับ';    }
      return o;
    }
    var teaching = (row.is_teaching==='TRUE');             // K
    if(teaching){
      o.subjGroup = row.subject+'  /  '+row.group;
      o.room = row.room; o.swappable = true;
      // F14: is this period inside a leave round, and marked as leave?
      var __lp = leavePeriodsFor(me, dateAbsentISO);        // null=no round
      if(__lp!==null){ o.hasRound=true; o.onLeave = __lp.indexOf(String(per))!==-1; }
      var ls = logStatusFor(log, me, dateAbsentISO, per);  // R / S
      if(ls.status===''){ o.status='ยังไม่ได้ค้นหา'; o.cls='todo'; }
      else if(ls.status==='ยกเลิก'){ o.status='ยกเลิก — ค้นหาใหม่'; o.cls='cancel'; }
      else {
        o.status = ls.status+'  ↔  '+ls.name; o.impact = ls.impact||'—';
        o.cls = (ls.status==='อนุมัติแล้ว')?'done':(ls.status==='รออนุมัติ')?'wait':'proposed';
      }
      return o;
    }
    // row exists but not teaching: B shows the activity string, C blank
    if(isLunch){ o.subjGroup='พักกลางวัน'; o.status='— (พักกลางวัน)'; }
    else       { o.subjGroup=row.room;     o.status='ไม่สามารถสลับได้'; }
    return o;
  }

